  <section class="cf-economy-section" aria-label="Manual perk fulfillment queue">
    <div><h2>Deliver perks, then record fulfillment</h2><p>{{ model.pendingCount }} pending. These are captured awards and purchases. Complete the external perk yourself; recording fulfillment updates this private queue.</p></div>
    <div class="cf-economy-queue-filters"><label class="cf-field"><span>Fulfillment status</span><select v-model="model.store.fulfillmentFilter" aria-label="Fulfillment status"><option value="pending">Pending</option><option value="fulfilled">Fulfilled</option><option value="all">All records</option></select></label><label class="cf-field"><span>Find viewer or perk</span><input v-model="model.store.fulfillmentSearch" aria-label="Find viewer or perk" type="search"></label></div>
    <ul class="cf-economy-queue"><li v-for="item in model.redemptions" :key="item.id"><div><h3>{{ item.rewardName }}</h3><p>{{ model.viewer(item.playerId) }} · <code>{{ item.playerId }}</code></p><p>{{ item.description }}</p><small>{{ item.acquisition }} · {{ model.date(item.createdAt) }} · {{ item.status }}</small><p v-if="item.fulfillmentNote">Private note: {{ item.fulfillmentNote }}</p></div><button v-if="item.status === 'pending'" type="button" class="cf-btn cf-btn-secondary" :disabled="model.store.busy" :aria-label="`Record fulfillment for ${item.rewardName} and ${model.viewer(item.playerId)}`" @click="model.openFulfillment(item)">Record fulfillment</button></li></ul>
